namespace ghidra.app.plugin.core.progmgr;

using docking.action;
using docking.action;
using docking.tool;
using ghidra.program.model.listing;
using ghidra.util;

/**
 * Action class for the "Close Program" action
 */
public class CloseProgramAction : AbstractProgramNameSwitchingAction {

	public CloseProgramAction(ProgramManagerPlugin plugin, string group, int subGroup) : base(plugin, "Close File")
    {
		MenuData menuData = new MenuData(new string[] { ToolConstants.MENU_FILE, "&Close" });
		menuData.setMenuGroup(group);
		menuData.setMenuSubGroup(Integer.toString(subGroup));
		setMenuBarData(menuData);
		setKeyBindingData(new KeyBindingData("ctrl w"));
	}

	/* @Override */
	protected void programChanged(Program program) {
		if (program == null) {
			getMenuBarData().setMenuItemName("&Close");
			setDescription("Close Program");
		}
		else {
			string progName = program.getDomainFile().getName();
			getMenuBarData().setMenuItemNamePlain("Close '%s'".formatted(progName));
			getMenuBarData().setMnemonic('C');
			setDescription("<html>Close '%s'".formatted(HTMLUtilities.escapeHTML(progName)));
		}
	}

	/* @Override */
	public void actionPerformed(Program program) {
		plugin.closeProgram(program, false);
	}

}
